CREATE TABLE IF NOT EXISTS commerce_migrations(id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,parent TEXT REFERENCES categories(id),kind TEXT CHECK(kind IN('pen','ink','craft')),version INTEGER NOT NULL DEFAULT 1);
INSERT OR IGNORE INTO categories(id,name,parent,kind) VALUES ('wugong','吾鋼 WUGONG',NULL,NULL),('change','藏娥',NULL,NULL);
INSERT OR IGNORE INTO categories(id,name,parent,kind) VALUES ('wugong-traditional','傳統工藝','wugong','pen'),('wugong-special','特殊筆款','wugong','pen'),('wugong-wood','世界奇木系列','wugong','pen'),('wugong-ink','手工墨水','wugong','ink'),('change-notebooks','筆記本','change','craft'),('change-ink','限定手工墨水','change','ink');
CREATE TABLE IF NOT EXISTS product_categories(sku TEXT PRIMARY KEY REFERENCES products(sku),category_id TEXT NOT NULL REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS promotions(code TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('fixed','percent','gift')),amount INTEGER NOT NULL CHECK(amount>=0),minimum INTEGER NOT NULL DEFAULT 0,maximum INTEGER NOT NULL CHECK(maximum>=0),scope TEXT NOT NULL CHECK(scope IN('all','family','category')),target TEXT NOT NULL DEFAULT '',starts TEXT NOT NULL,ends TEXT NOT NULL,quota INTEGER NOT NULL CHECK(quota>0),active INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,gift_text TEXT NOT NULL DEFAULT '',gift_kind TEXT NOT NULL DEFAULT 'other' CHECK(gift_kind IN('ink','other')));
CREATE TABLE IF NOT EXISTS promotion_claims(code TEXT NOT NULL REFERENCES promotions(code),member_id TEXT NOT NULL,order_number TEXT NOT NULL UNIQUE REFERENCES orders(order_number),discount INTEGER NOT NULL CHECK(discount>=0),PRIMARY KEY(code,member_id));
CREATE TABLE IF NOT EXISTS order_gifts(order_number TEXT PRIMARY KEY REFERENCES orders(order_number),description TEXT NOT NULL,kind TEXT NOT NULL);
INSERT OR IGNORE INTO promotions(code,kind,amount,minimum,maximum,scope,target,starts,ends,quota,active,version) SELECT code,kind,amount,minimum,maximum,scope,target,starts,ends,quota,active,version FROM coupons WHERE NOT EXISTS(SELECT 1 FROM commerce_migrations WHERE id='categories-gifts-v1');
INSERT OR IGNORE INTO promotion_claims SELECT code,member_id,order_number,discount FROM coupon_claims WHERE NOT EXISTS(SELECT 1 FROM commerce_migrations WHERE id='categories-gifts-v1');
INSERT OR IGNORE INTO commerce_migrations VALUES ('categories-gifts-v1');
